<?php
require_once __DIR__.'/../../../app/bootstrap.php';
require_once __DIR__.'/../../../app/Modules/Marketplace/Marketplace.php';
Auth::requireRole(['super_admin','owner']);
$pageTitle='Laporan Ongkir Kurir Toko';$db=Database::connect();marketplace_install($db);
$from=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['from']??''))?$_GET['from']:date('Y-m-01');
$to=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['to']??''))?$_GET['to']:date('Y-m-d');
$subdistrict=trim((string)($_GET['subdistrict']??''));$courierId=max(0,(int)($_GET['courier_id']??0));
$where=["o.courier_code='store'","o.payment_status='paid'","DATE(COALESCE(o.paid_at,o.created_at)) BETWEEN ? AND ?"];$params=[$from,$to];
if($subdistrict!==''){$where[]='o.subdistrict=?';$params[]=$subdistrict;}if($courierId>0){$where[]='a.courier_id=?';$params[]=$courierId;}
$sql="SELECT o.id,o.order_number,o.recipient_name,o.subdistrict,o.district,o.city,o.shipping_cost,o.shipping_discount,o.grand_total,o.paid_at,o.created_at,o.order_status,a.status courier_status,c.id courier_id,c.name courier_name FROM online_orders o LEFT JOIN marketplace_courier_assignments a ON a.order_id=o.id LEFT JOIN marketplace_couriers c ON c.id=a.courier_id WHERE ".implode(' AND ',$where)." ORDER BY COALESCE(o.paid_at,o.created_at) DESC,o.id DESC";
$s=$db->prepare($sql);$s->execute($params);$rows=$s->fetchAll()?:[];
$totalGross=0;$totalDiscount=0;foreach($rows as $r){$totalGross+=(float)$r['shipping_cost'];$totalDiscount+=(float)($r['shipping_discount']??0);} $net=max(0,$totalGross-$totalDiscount);
$subdistricts=[];try{$subdistricts=$db->query("SELECT DISTINCT subdistrict FROM online_orders WHERE courier_code='store' AND subdistrict<>'' ORDER BY subdistrict")->fetchAll(PDO::FETCH_COLUMN)?:[];}catch(Throwable $e){}
$couriers=marketplace_store_courier_active($db,null);
$query=http_build_query(['from'=>$from,'to'=>$to,'subdistrict'=>$subdistrict,'courier_id'=>$courierId]);
require __DIR__.'/../../layouts/admin-header.php';require __DIR__.'/../../layouts/admin-sidebar.php';
?>
<main class="admin-main"><header class="admin-topbar"><button class="sidebar-toggle" id="sidebarToggle"><i class="bi bi-list"></i></button><div class="topbar-title"><h1>Laporan Ongkir Kurir Toko</h1><p>Pemasukan ongkir Kurir Toko dipisahkan dari omzet barang.</p></div><div class="topbar-actions"><a class="btn-soft" href="<?=legacy_base_url('admin/marketplace-courier-income/export.php?'.$query)?>"><i class="bi bi-file-earmark-excel"></i> Excel</a></div></header>
<section class="premium-card mt-4"><form method="get" class="premium-form"><div class="form-grid"><div class="form-group"><label>Dari</label><input type="date" name="from" value="<?=e($from)?>"></div><div class="form-group"><label>Sampai</label><input type="date" name="to" value="<?=e($to)?>"></div><div class="form-group"><label>Kelurahan</label><select name="subdistrict"><option value="">Semua</option><?php foreach($subdistricts as $x):?><option <?=($subdistrict===$x)?'selected':''?>><?=e($x)?></option><?php endforeach;?></select></div><div class="form-group"><label>Kurir</label><select name="courier_id"><option value="0">Semua</option><?php foreach($couriers as $c):?><option value="<?=$c['id']?>" <?=$courierId===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div></div><div class="form-actions"><button class="btn-premium"><i class="bi bi-filter"></i> Terapkan</button></div></form></section>
<section class="finance-summary-grid mt-4"><div class="finance-summary-card"><span>Order Kurir Toko</span><h3><?=count($rows)?></h3></div><div class="finance-summary-card"><span>Ongkir Kotor</span><h3><?=rupiah($totalGross)?></h3></div><div class="finance-summary-card"><span>Subsidi/Voucher Ongkir</span><h3><?=rupiah($totalDiscount)?></h3></div><div class="finance-summary-card"><span>Pemasukan Ongkir Bersih</span><h3><?=rupiah($net)?></h3></div></section>
<section class="premium-card mt-4"><div class="card-head"><div><h3>Rincian Pemasukan</h3><p>Hanya order Kurir Toko dengan pembayaran berstatus paid.</p></div></div><div class="table-responsive"><table class="premium-table"><thead><tr><th>Tanggal</th><th>Order</th><th>Tujuan</th><th>Kurir</th><th>Ongkir</th><th>Subsidi</th><th>Bersih</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): $n=max(0,(float)$r['shipping_cost']-(float)$r['shipping_discount']); ?><tr><td><?=e(date('d/m/Y H:i',strtotime($r['paid_at']?:$r['created_at'])))?></td><td><b><?=e($r['order_number'])?></b><br><small><?=e($r['recipient_name'])?></small></td><td><?=e($r['subdistrict'])?><br><small><?=e($r['district'].', '.$r['city'])?></small></td><td><?=e($r['courier_name']?:'Belum ditugaskan')?></td><td><?=rupiah($r['shipping_cost'])?></td><td><?=rupiah($r['shipping_discount'])?></td><td><b><?=rupiah($n)?></b></td><td><?=e(ucwords(str_replace('_',' ',$r['order_status'])))?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8">Belum ada pemasukan ongkir pada periode ini.</td></tr><?php endif;?></tbody></table></div></section></main>
<?php require __DIR__.'/../../layouts/admin-footer.php';?>
